$('#layer-list').addEventListener('dragstart',e=>{const row=e.target.closest('[data-select]');if(row){draggedLayer=row.dataset.select;e.dataTransfer.setData('text/plain',draggedLayer);e.dataTransfer.effectAllowed='move';}});
$('#layer-list').addEventListener('dragover',e=>{if(draggedLayer)e.preventDefault();});
$('#layer-list').addEventListener('drop',e=>{e.preventDefault();const row=e.target.closest('[data-select]');if(!row||!draggedLayer)return;const from=doc.layers.findIndex(l=>l.id===draggedLayer),to=doc.layers.findIndex(l=>l.id===row.dataset.select);if(from>=0&&to>=0){const [l]=doc.layers.splice(from,1);doc.layers.splice(to,0,l);commit();renderCanvas();renderLayers();}draggedLayer=null;});
$('#layer-list').addEventListener('dragend',()=>{draggedLayer=null;});

const shell=$('#artboard-shell');
function artboardPoint(e){const rect=shell.getBoundingClientRect();return {x:(e.clientX-rect.left)/sceneScale,y:(e.clientY-rect.top)/sceneScale};}
function renderGuides(){ $('#guide-overlay').innerHTML=guides.map(g=>`<span class="alignment-guide ${g.axis==='x'?'vertical':'horizontal'}" style="${g.axis==='x'?'left':'top'}:${g.position*sceneScale}px"></span>`).join(''); }
function alignSelected(direction){const l=selected();if(!l)return;const bounds=rotatedBounds(l);if(direction==='left')l.cx-=bounds.left;if(direction==='right')l.cx+=doc.width-bounds.right;if(direction==='center-x')l.cx=doc.width/2;if(direction==='top')l.cy-=bounds.top;if(direction==='bottom')l.cy+=doc.height-bounds.bottom;if(direction==='center-y')l.cy=doc.height/2;commit();renderCanvas();renderPanel();}
shell.addEventListener('pointerdown',e=>{if(e.button!==0)return;const handle=e.target.closest('[data-handle]');const object=e.target.closest('[data-layer-id]');if(!handle&&!object){selectedId=null;renderSelection();renderLayers();return;}if(object)selectLayer(object.dataset.layerId,true);let l=selected();if(!l)return;if(e.altKey&&!handle){l={...copy(l),id:uid(),name:`${l.name} copy`};doc.layers.push(l);selectedId=l.id;renderCanvas();renderLayers();}e.preventDefault();shell.focus({preventScroll:true});const p=artboardPoint(e);drag={id:l.id,start:p,original:copy(l),handle:handle?.dataset.handle||'move'};shell.setPointerCapture(e.pointerId);});
shell.addEventListener('pointermove',e=>{if(!drag)return;const l=doc.layers.find(l=>l.id===drag.id);if(!l)return;const p=artboardPoint(e),o=drag.original;guides=[];
if(drag.handle==='move'){let dx=p.x-drag.start.x,dy=p.y-drag.start.y;if(e.shiftKey){if(Math.abs(dx)>Math.abs(dy))dy=0;else dx=0;}l.cx=o.cx+dx;l.cy=o.cy+dy;if(snapEnabled&&!e.metaKey&&!e.ctrlKey){const snapped=snapMove(l,doc,7/sceneScale);l.cx=snapped.cx;l.cy=snapped.cy;guides=snapped.guides;}}
else if(drag.handle==='rotate'){const start=Math.atan2(drag.start.y-o.cy,drag.start.x-o.cx);let degrees=o.rotation+(Math.atan2(p.y-o.cy,p.x-o.cx)-start)*180/Math.PI;if(e.shiftKey)degrees=Math.round(degrees/15)*15;l.rotation=Math.round(degrees);}
else Object.assign(l,scaleFromCorner(o,p,drag.handle,{fromCenter:e.altKey,locked:o.locked!==false}));
const group=$(`[data-layer-id="${l.id}"]`);if(group){if(drag.handle==='move'||drag.handle==='rotate')group.setAttribute('transform',transform(l));else{cache.delete(l.id);$('#scene').innerHTML=sceneMarkup({preview:true});}}renderSelection();renderGuides();});
function endDrag(){if(!drag)return;drag=null;guides=[];renderGuides();commit();renderPanel();renderLayers();}
shell.addEventListener('pointerup',endDrag);shell.addEventListener('pointercancel',()=>{if(drag){const l=doc.layers.find(l=>l.id===drag.id);if(l)Object.assign(l,drag.original);drag=null;guides=[];renderGuides();render();}});
new ResizeObserver(()=>{fitCanvas();renderSelection();}).observe($('#canvas-viewport'));

function editable(target){return target instanceof Element&&(target.closest('input,textarea,select,[contenteditable="true"]'));}
document.addEventListener('keydown',e=>{if(e.defaultPrevented||editable(e.target))return;const mod=e.metaKey||e.ctrlKey;if(mod&&e.key.toLowerCase()==='u'){e.preventDefault();$('#snap-toggle').click();return;}if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey?1:-1);return;}if(mod&&e.key.toLowerCase()==='d'){e.preventDefault();duplicateSelected();return;}if(e.key==='Escape'){selectedId=null;renderSelection();renderLayers();return;}if(['Delete','Backspace'].includes(e.key)){e.preventDefault();deleteSelected();return;}const l=selected();if(l&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const amount=e.shiftKey?10:1;if(e.key==='ArrowLeft')l.cx-=amount;if(e.key==='ArrowRight')l.cx+=amount;if(e.key==='ArrowUp')l.cy-=amount;if(e.key==='ArrowDown')l.cy+=amount;renderCanvas();deferCommit();renderPanel();}});
document.addEventListener('paste',async e=>{if(editable(e.target))return;const text=e.clipboardData.getData('image/svg+xml')||e.clipboardData.getData('text/plain')||e.clipboardData.getData('text/html');const svg=text.match(/<svg[\s\S]*?<\/svg>/i)?.[0];if(svg){e.preventDefault();await importVector(svg);return;}const files=[...e.clipboardData.files];if(files.length){e.preventDefault();for(const f of files){if(f.type==='image/svg+xml')await importVector(await f.text(),f.name);else if(f.type.startsWith('image/'))await importImage(f);}}});
const viewport=$('#canvas-viewport');
viewport.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();viewport.classList.add('drag-over');}});
viewport.addEventListener('dragleave',e=>{if(!viewport.contains(e.relatedTarget))viewport.classList.remove('drag-over');});
viewport.addEventListener('drop',async e=>{e.preventDefault();viewport.classList.remove('drag-over');for(const file of e.dataTransfer.files){if(file.type==='image/svg+xml'||/\.svg$/i.test(file.name))await importVector(await file.text(),file.name,activeTab==='layout');else await importImage(file,activeTab==='layout');}});

let fontsPromise;
async function exportFonts(){return fontsPromise ||= Promise.all([['./assets/Aeonik Pro TRIAL/AeonikProTRIAL-Regular.otf','Aeonik','opentype',400],['./assets/Signifier/Signifier-Light.ttf','Signifier','truetype',300]].map(async([path,font,format,weight])=>{const response=await fetch(path);if(!response.ok)throw new Error(`Could not load ${font}.`);const blob=await response.blob();const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});return `@font-face{font-family:${font};font-weight:${weight};src:url('${data}') format('${format}');}`;})).then(parts=>parts.join(''));}
function openExport(){$('#export-dimensions').textContent=`${doc.width.toLocaleString()} × ${doc.height.toLocaleString()} px · ${doc.layers.filter(l=>l.visible).length} visible layers`;$('#export-dialog').showModal();}
$('#export-open').addEventListener('click',openExport);
function download(blob,extension){const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`One-Innovation-${doc.width}x${doc.height}.${extension}`;a.click();setTimeout(()=>URL.revokeObjectURL(url),15000);}
async function exportArtwork(type){if(busyCount){toast('Wait for image processing to finish, then export.');return;}const button=$(`#export-${type}`);button.disabled=true;try{await document.fonts.ready;const fonts=await exportFonts();const transparent=$('#export-transparent').checked;let svg=sceneMarkup({fonts,transparent});if(type==='svg')download(new Blob([svg],{type:'image/svg+xml;charset=utf-8'}),'svg');else{const scale=Number($('#export-scale').value);const width=doc.width*scale,height=doc.height*scale;if(width>16384||height>16384||width*height>65000000)throw new Error('This PNG is too large. Choose original size or a smaller artboard.');svg=svg.replace(/width="[^"]+" height="[^"]+"/,`width="${doc.width}" height="${doc.height}"`);const blob=new Blob([svg],{type:'image/svg+xml;charset=utf-8'});const url=URL.createObjectURL(blob);try{const image=await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(new Error('Could not render the PNG. Try SVG export.'));img.src=url;});const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;canvas.getContext('2d').drawImage(image,0,0,width,height);const png=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!png)throw new Error('Could not create PNG at this size.');download(png,'png');}finally{URL.revokeObjectURL(url);}}toast(`${type.toUpperCase()} exported.`);$('#export-dialog').close();}catch(e){toast(e.message);}finally{button.disabled=false;}}
$('#export-svg').addEventListener('click',()=>exportArtwork('svg'));$('#export-png').addEventListener('click',()=>exportArtwork('png'));

async function boot(){try{const db=await storage();const saved=await new Promise((resolve,reject)=>{const request=db.transaction('documents').objectStore('documents').get('current');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});if(saved?.version===2&&Array.isArray(saved.layers)&&saved.width>0&&saved.height>0){doc=saved;selectedId=doc.layers[0]?.id||null;}}catch{saveMessage='Session only · storage unavailable';}doc.background2 ||= BRAND[1];doc.backgroundAngle ??=90;doc.backgroundGradient ??=false;if(!hasRememberedColorMode){const v=activeVisual();colorMode=doc.backgroundGradient||!SETS.some(colors=>doc.background.toUpperCase()===colors[0]&&(!v||v.color.toUpperCase()===colors[1]))?'manual':'palette';}for(const l of doc.layers){if(l.kind==='visual'){ensureFilterSettings(l);delete l.particleSquareness;l.gradient=false;if(!l.vectorSource&&l.foundationRevision!==FOUNDATION_REVISION)setFoundation(l,l.type);refreshVisual(l);}}commit();render();document.fonts.ready.then(()=>{cache.clear();renderCanvas();});}
render();boot();
